SELECT *
FROM cinema c
WHERE c.multiplex_id = #{multiplexId}

    AND c.area_id = #{areaId}

SELECT *
FROM screen s
WHERE s.multiplex_id = #{multiplexId}

    AND s.cinema_id = #{cinemaId}

SELECT p.*, m.multiplex_name, c.cinema_name, COALESCE(pc.comment_count, 0) AS comment_count FROM post p LEFT JOIN multiplex m ON p.multiplex_id = m.multiplex_id LEFT JOIN cinema c ON p.cinema_id = c.cinema_id LEFT JOIN ( SELECT post_id, COUNT(*) AS comment_count FROM post_comment GROUP BY post_id ) pc ON p.post_id = pc.post_id WHERE 1=1
AND p.multiplex_id = #{multiplexId}
AND p.area_id = #{areaId}
AND p.cinema_id = #{cinemaId}
AND p.screen_id = #{screenId}
ORDER BY p.views DESC, p.post_id DESC
ORDER BY COALESCE(pc.comment_count, 0) DESC, p.post_id DESC
ORDER BY p.created_at DESC, p.post_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM post p
WHERE 1=1

    AND p.multiplex_id = #{multiplexId}


    AND p.area_id = #{areaId}


    AND p.cinema_id = #{cinemaId}


    AND p.screen_id = #{screenId}

SELECT u.user_id, u.nickname
FROM users u
WHERE u.user_id =#{id}

SELECT p.post_id, COUNT(*) AS commentCount FROM post_comment p WHERE p.post_id IN
#{id}
GROUP BY p.post_id

SELECT  COUNT(*)
FROM post_comment p
WHERE p.post_id =#{id}

SELECT *
FROM post_comment p
WHERE p.post_id = #{postId}

